            new Quote { Id = "https://it.wikiquote.org/wiki/Tommaso_Campanella", Text = "Le leggi son pochissime, tutte scritte in una tavola di rame alla porta del tempio, cioè nelle colonne, nelle quali ci sono scritte tutte le quiddità delle cose in breve.", Author = "Tommaso Campanella" },
